def transform(grid):
    from collections import Counter
    n = len(grid)
    tiles = []
    for br in range(0, n, 6):
        for bc in range(0, n, 6):
            tiles.append([[grid[br+r][bc+c] for c in range(5)] for r in range(5)])
    common = tuple(tuple(row) for row in max(Counter(tuple(tuple(row) for row in t) for t in tiles), key=lambda t: Counter(tuple(tuple(row) for row in t) for t in tiles)[t]))
    out = [list(row) for row in common]
    # Recolor the diagonal band (bottom-left to top-right) blue.
    for r in range(5):
        for c in range(5):
            if out[r][c] != 8 and not (r == 4 and c == 2) and not (r == 0 and c == 0) and not (r == 4 and c == 3) and not (r == 1 and c == 2) and not (r == 2 and c == 2) and not (r == 2 and c == 4):
                out[r][c] = 1
    return out
